import os, re, pathlib, stat, hashlib, json, sqlite3, subprocess, sys

# Load .env passwords without printing them
env_path = "/opt/projects/active/odoo-sh-local-mock/.env"
pw_map = {}
with open(env_path) as f:
    for line in f:
        line=line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        k,v=line.split("=",1)
        if "POSTGRES" in k and "PASSWORD" in k:
            pw_map[k]=v

# Also check .env.example defaults (should be placeholder)
# Search roots
roots = [
    "/tmp/p3-canary-p3_20260905T071700Z_d1938642",
    "/tmp/p3-helpers-erp-cloud-p3",
    "/opt/projects/active/odoo-sh-local-mock/docs/reports/evidence",
    "/opt/projects/active/odoo-sh-local-mock/docs/reports",
    "/tmp",
]

# Also check Roo bridge and cli dirs
import glob
roo_dirs = glob.glob("/tmp/roo-*") + glob.glob("/tmp/roo-cli-*") + glob.glob("/home/sabry/.roo")

# Collect files to inspect
candidates = []
for root in roots:
    if os.path.isdir(root):
        for dirpath, _, files in os.walk(root):
            # skip huge dirs like /tmp/systemd-private etc already filtered
            if "systemd-private" in dirpath or "snap-private" in dirpath:
                continue
            for fn in files:
                fp = os.path.join(dirpath, fn)
                # limit to text-like files
                if os.path.getsize(fp) > 5*1024*1024:
                    continue
                candidates.append(fp)
for d in roo_dirs:
    if os.path.isdir(d):
        for dirpath, _, files in os.walk(d):
            for fn in files:
                fp=os.path.join(dirpath, fn)
                if os.path.getsize(fp) > 5*1024*1024:
                    continue
                candidates.append(fp)

# Also add specific files
extra = [
    "/opt/projects/active/odoo-sh-local-mock/.env",
    "/opt/projects/active/odoo-sh-local-mock/docker-compose.yml",
]
for fp in extra:
    if os.path.exists(fp):
        candidates.append(fp)

# Deduplicate
candidates = sorted(set(candidates))

# Search safely: do not print secret values, only report presence
