                perms = oct(st.st_mode)[-3:]
                owner = st.st_uid
            except:
                perms = "?"
                owner = "?"
            # Check if retained by Roo/bridge: path contains roo
            retained = "roo" in fp.lower() or "bridge" in fp.lower()
            # Check if still valid: try to connect? We'll do later
            results.append((fp, k, "complete", perms, retained))
        # Also check for partial: first 8 chars
        elif pw[:8] in content and "POSTGRES" in content:
            try:
                st = os.stat(fp)
                perms = oct(st.st_mode)[-3:]
            except:
                perms = "?"
            retained = "roo" in fp.lower() or "bridge" in fp.lower()
            results.append((fp, k, "partial", perms, retained))

